async function progress(){
  for (let i=0; i<30; i++) {
    const ls = [...document.querySelectorAll('.passage a.macro-linkreplace')];
    if (!ls.length) return {done: i, reason: 'no-linkreplace'};
    ls[0].click();
    await new Promise(r => setTimeout(r, 500));
  }
  return {done: 30, reason: 'max-iterations'};
}
return await progress();

